import {PERMISSIONS,ROLE_PERMISSIONS,DEPENDS} from './shared/team-state.js?v=5.8.0';
import {teamRead} from './shared/team-storage.js?v=5.8.0';
import {teamRequest,staffLink} from './shared/team-live.js?v=5.25.1';
import {TEAM_LIVE_COPY} from './shared/team-live-copy.js?v=5.11.0';
import {expansionCopy} from './shared/expansion-copy.js?v=5.8.0';
import {brandMark} from './shared/brand.js?v=5.6.0';
import {CLOUD} from './shared/cloud-config.js?v=5.6.0';
import {esc,icon} from './shared/core.js?v=5.6.0';
import {formatDateTime} from './shared/locale.js?v=5.6.0';
const copy=l=>({...expansionCopy(l),...TEAM_LIVE_COPY[l]});
const cacheKey=(store,id)=>`one-shop-staff-issued:${store}:${id}`;
export function rememberStaffLink(store,result){if(result.token)localStorage.setItem(cacheKey(store,result.member.id),JSON.stringify({token:result.token,expiresAt:result.member.expiresAt}));}
function issued(store,member,lang){try{const value=JSON.parse(localStorage.getItem(cacheKey(store,member.id)));return value?.expiresAt===member.expiresAt?staffLink(store,member.id,value.token,lang):null;}catch{return null;}}
export async function importSampleTeam(credential){const old=teamRead(),current=await teamRequest(credential.storeId,'team','GET',null,credential.token);for(const member of old.teamMembers){if(current.members.some(m=>m.name===member.name&&m.role===member.role))continue;const result=await teamRequest(credential.storeId,'team','POST',{name:member.name,role:member.role,permissions:member.permissions},credential.token);rememberStaffLink(credential.storeId,result);current.members.push(result.member);}}
const permissions=(list,c)=>PERMISSIONS.map(p=>`<label><input type="checkbox" name="permission" value="${p}" ${list.includes(p)?'checked':''}><span>${esc(c[p])}</span></label>`).join('');
export function teamMarkup(lang,{sample=false,live=null,storeId=''}={}){const c=copy(lang);if(sample)return `<section class="team-panel"><header class="team-heading">${brandMark('greeting',true)}<div><h1>${esc(c.connectTitle)}</h1><p>${esc(c.connectBody)}</p></div></header><button class="button primary" data-action="team-connect">${esc(c.connect)}${icon('arrow')}</button><p class="team-boundary">${esc(c.deviceNote)}</p></section>`;
 if(!live?.data)return `<section class="team-panel" id="team-panel"><h1>${esc(c.team)}</h1><p role="status">${esc(c[live?.status]||c.connecting)}</p><button class="button" data-team-refresh>${esc(c.retry)}</button></section>`;
 const s=live.data;return `<section class="team-panel" id="team-panel"><header class="team-heading">${brandMark('greeting',true)}<div><small>${esc(c.superAdmin)} · ${esc(c.live)}</small><h1>${esc(c.team)}</h1><p>${esc(c.liveNote)}</p></div></header><div class="team-live-links"><a class="button primary" href="${esc(CLOUD.guestBase+'?store='+storeId+'&lang='+lang+'&table=7')}" target="_blank" rel="noopener noreferrer">${esc(c.guestTest)}${icon('arrow')}</a></div><p class="team-boundary">${esc(c.linkNote)}</p><form data-team-register><h2>${esc(c.register)}</h2><div class="team-form-row"><label>${esc(c.memberName)}<input name="name" maxlength="30" required autocomplete="off"></label><label>${esc(c.role)}<select name="role" data-team-role>${['floor','kitchen','custom'].map(r=>`<option value="${r}">${esc(c[r])}</option>`).join('')}</select></label></div><fieldset class="team-permissions"><legend>${esc(c.permissions)}</legend>${permissions(ROLE_PERMISSIONS.floor,c)}</fieldset><button class="button primary" type="submit">${esc(c.register)}</button></form><p class="team-feedback" role="status" aria-live="polite"></p><div class="team-members">${s.members.map(m=>{const url=issued(storeId,m,lang);return `<article class="team-member" data-member="${m.id}"><header><div><h2>${esc(m.name)}</h2><small>${esc(c[m.role])} · ${esc(c.expires)} ${esc(formatDateTime(m.expiresAt,lang))}</small></div>${url?`<a class="button" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(c.openStaff)}${icon('arrow')}</a>`:''}</header><form data-team-edit="${m.id}" data-revision="${m.revision}"><fieldset class="team-permissions"><legend>${esc(c.permissions)}</legend>${permissions(m.permissions,c)}</fieldset><div class="team-actions"><button class="button" type="submit">${esc(c.save)}</button>${url?`<button class="button" type="button" data-team-copy="${m.id}">${esc(c.copyLink)}</button>`:''}<button class="button" type="button" data-team-rotate="${m.id}">${esc(c.issueLink)}</button><button class="button danger" type="button" data-team-remove="${m.id}">${esc(c.remove)}</button></div></form>${url?`<details class="team-link"><summary>${esc(c.openStaff)}</summary><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(url)}</a></details>`:`<p class="team-hint">${esc(c.inviteUnavailable)}</p>`}</article>`;}).join('')||`<p>${esc(c.noStaff)}</p>`}</div><aside class="team-policy"><h2>${esc(c.ownerOnly)}</h2><p>${esc(c.bookLogic)}</p><p>${esc(c.deviceNote)}</p></aside><section class="team-audit"><h2>${esc(c.audit)}</h2>${s.audit.length?s.audit.slice(0,12).map(a=>`<p><b>${esc(a.actor==='owner'?c.superAdmin:a.actor)}</b><span>${esc(auditLabel(a.action,c))} · ${esc(a.target)}</span><small>${esc(formatDateTime(a.at,lang))}</small></p>`).join(''):`<p>${esc(c.emptyAudit)}</p>`}</section></section>`;}
function auditLabel(action,c){return ({create:c.register,register:c.register,permissions:c.permissions,revoke:c.remove,rotate:c.issueLink,menu:c.menuEdit,settings:c.settingsEdit,booking:c.bookingAccept,'order:accepted':c.ordersAccept,'order:preparing':c.ordersPrepare,'order:ready':c.ordersPrepare,'order:completed':c.ordersServe})[action]||action;}
export function bindTeam(host,lang,refresh,{live,storeId}={}){if(!host||!live)return ()=>{};const c=copy(lang);let confirming='';const note=text=>{const el=document.querySelector('.team-feedback');if(el){el.textContent=text;el.scrollIntoView({block:'nearest'});}};const run=async fn=>{if(live.busy)return;host.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();refresh();note(c.saved);}catch(e){refresh();note(c[e.message]||c.connectFailed);}};
 const submit=e=>{const form=e.target;if(!form.matches('[data-team-register],[data-team-edit]'))return;e.preventDefault();const data=new FormData(form);run(async()=>{const result=await live.mutate(form.hasAttribute('data-team-register')?'team':'team/'+form.dataset.teamEdit,form.hasAttribute('data-team-register')?'POST':'PATCH',form.hasAttribute('data-team-register')?{name:data.get('name'),role:data.get('role'),permissions:data.getAll('permission')}:{operation:'permissions',revision:Number(form.dataset.revision),permissions:data.getAll('permission')});rememberStaffLink(storeId,result);});};
 const change=e=>{if(e.target.matches('[data-team-role]'))e.target.form.querySelectorAll('[name=permission]').forEach(x=>x.checked=ROLE_PERMISSIONS[e.target.value].includes(x.value));if(e.target.name==='permission'){const inputs=[...e.target.form.querySelectorAll('[name=permission]')];if(e.target.checked&&DEPENDS[e.target.value])inputs.find(x=>x.value===DEPENDS[e.target.value]).checked=true;if(!e.target.checked)inputs.filter(x=>DEPENDS[x.value]===e.target.value).forEach(x=>x.checked=false);}};
 const click=async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-team-refresh')){live.invalidate();return;}if(b.dataset.teamCopy){const m=live.data?.members.find(m=>m.id===b.dataset.teamCopy),url=m&&issued(storeId,m,lang);if(!url)return;try{await navigator.clipboard.writeText(url);note(c.copied);}catch{note(c.linkUnavailable);}}
  const id=b.dataset.teamRemove||b.dataset.teamRotate;if(!id)return;const operation=b.dataset.teamRemove?'revoke':'rotate',key=operation+id;if(confirming!==key){confirming=key;b.textContent=operation==='revoke'?c.removeConfirm:c.rotateConfirm;return;}const m=live.data?.members.find(x=>x.id===id);if(!m)return;run(async()=>{const result=await live.mutate('team/'+id,'PATCH',{operation,revision:m.revision});if(operation==='revoke')localStorage.removeItem(cacheKey(storeId,id));else rememberStaffLink(storeId,result);});
 };host.addEventListener('submit',submit);host.addEventListener('change',change);host.addEventListener('click',click);return ()=>{host.removeEventListener('submit',submit);host.removeEventListener('change',change);host.removeEventListener('click',click);};}
export function teamBook(lang){const c=copy(lang);return `<section class="book-team" id="team-access"><header>${brandMark('greeting',true)}<div><h3>${esc(c.teamLead)}</h3><p>${esc(c.liveNote)}</p></div></header><div class="team-book-roles"><article><h4>${esc(c.superAdmin)}</h4><p>${esc(c.ownerOnly)}</p></article><article><h4>${esc(c.floor)}</h4><p>${esc(c.floorNote)}</p></article><article><h4>${esc(c.kitchen)}</h4><p>${esc(c.kitchenNote)}</p></article></div><div class="team-book-logic"><p>${esc(c.bookLogic)}</p><p>${esc(c.alternative)}</p></div><div class="cover-actions"><a class="button primary" href="jumo/owner.html?lang=${lang}#team" target="_blank" rel="noopener">${esc(c.openTeam)}${icon('arrow')}</a><a class="button secondary" href="#apps">${esc(c.floor)} · ${esc(c.rolePreview)}</a><a class="button secondary" href="#apps">${esc(c.kitchen)} · ${esc(c.rolePreview)}</a></div><p>${esc(c.bookBoundary)}</p><p class="team-hint">${esc(c.linkNote)}</p></section>`;}
